-- =====================================================================
-- ThermoCare IoT · Datos simulados para el dashboard
-- 5 pacientes, 7 días de lecturas cada 10 minutos (unas 5,000), alertas,
-- medicamentos y ondas de calor. Las fechas se calculan con NOW().
-- BORRA los datos actuales (no las tablas). Ejecutar después del script
-- de creación de la base de datos.
-- =====================================================================
USE thermocare;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE ALERTA;
TRUNCATE TABLE MEDICAMENTO;
TRUNCATE TABLE ONDA_CALOR;
TRUNCATE TABLE LECTURA;
TRUNCATE TABLE TRATA;
TRUNCATE TABLE APOYA;
TRUNCATE TABLE TELEFONO_PERSONAL;
TRUNCATE TABLE TELEFONO_APOYO;
TRUNCATE TABLE PACIENTE;
TRUNCATE TABLE PERSONAL_MEDICO;
TRUNCATE TABLE PERSONA_APOYO;
TRUNCATE TABLE DISPOSITIVO;
SET FOREIGN_KEY_CHECKS = 1;

